# ADR-0070. The deployment facility runs on a build runner, a CI job and a
# deployment host — none of which has a database, a web framework or a tenant,
# and none of which should acquire one in order to validate a descriptor. This
# is the same one-way shape `dotmac-ui` holds, for the same reason.
#
# Stated as its own contract rather than folded into "Modules must not import
# the assembly" because the facility is NOT a module: it has no manifest, no
# `mod_*` namespace and no lineage, and filing it with the modules would send
# the next reader looking for all three.
name = "The deployment foundation must not import the kernel, the UI or the assembly"
type = "forbidden"
source_modules = ["dotmac_deployment_foundation"]
forbidden_modules = ["app", "dotmac_kernel", "dotmac_ui"]

[[tool.importlinter.contracts]]
# The other direction, and the one that actually decays. Nothing stops an
# application service from importing a renderer "just to read the descriptor",
# and the first one that does makes the facility a runtime dependency of the
# product it is supposed to deploy.
name = "The assembly and the kernel must not import the deployment foundation"
type = "forbidden"
source_modules = ["app", "dotmac_kernel"]
forbidden_modules = ["dotmac_deployment_foundation"]

