"""Course catalog service — discovery + structure for learners and staff."""

from __future__ import annotations

from collections import defaultdict
from uuid import UUID

from sqlalchemy import func, select
from sqlalchemy.orm import Session

from .catalog_contracts import (
    CatalogActivity,
    CatalogChapter,
    CatalogPart,
    CourseStructure,
)
from .curriculum import _fact as _chapter_fact
from .curriculum_contracts import ChapterFact
from .curriculum_models import Chapter
from .entitlements import unmet_prerequisites, visible_course_ids
from .models import Activity, Course
from .projections import best_scores_for
from .references import CourseFact, _activity_fact, _course_fact


def my_courses(
    db: Session, *, tenant_id: UUID, person_id: UUID
) -> tuple[CourseFact, ...]:
    """Courses the person is entitled to see, ordered by title."""
    ids = visible_course_ids(db, tenant_id=tenant_id, person_id=person_id)
    if not ids:
        return ()
    return tuple(
        _course_fact(row)
        for row in db.scalars(
            select(Course)
            .where(Course.tenant_id == tenant_id)
            .where(Course.id.in_(ids))
            .order_by(Course.title)
        ).all()
    )


def all_courses(db: Session, *, tenant_id: UUID) -> tuple[CourseFact, ...]:
    """Every course belonging to the tenant, ordered by title."""
    return tuple(
        _course_fact(row)
        for row in db.scalars(
            select(Course).where(Course.tenant_id == tenant_id).order_by(Course.title)
        ).all()
    )


def course_completion(
    db: Session, *, tenant_id: UUID, person_id: UUID, course_id: UUID
) -> int:
    """Return passed activities / total activities as an integer 0-100.

    Returns 0 for courses with no activities.
    """
    total = (
        db.scalar(
            select(func.count())
            .select_from(Activity)
            .where(Activity.tenant_id == tenant_id)
            .where(Activity.course_id == course_id)
        )
        or 0
    )
    if total == 0:
        return 0
    best = best_scores_for(
        db, tenant_id=tenant_id, person_id=person_id, course_id=course_id
    )
    passed = sum(1 for s in best.values() if s.passed)
    return round(100 * passed / total)


def course_structure(
    db: Session, *, tenant_id: UUID, person_id: UUID, course_id: UUID
) -> CourseStructure:
    """Group source chapters/activities and select the first unfinished chapter.

    Only the first encountered activity in each chapter drives Continue. Empty
    chapters qualify; course-level activities do not. Activity query ties remain
    unspecified exactly as in Academy. This read applies no entitlement guard.
    """
    locked = bool(
        unmet_prerequisites(
            db, tenant_id=tenant_id, person_id=person_id, course_id=course_id
        )
    )
    best = best_scores_for(
        db, tenant_id=tenant_id, person_id=person_id, course_id=course_id
    )

    chapters = list(
        db.scalars(
            select(Chapter)
            .where(Chapter.tenant_id == tenant_id)
            .where(Chapter.course_id == course_id)
            .order_by(Chapter.order_index, Chapter.number)
        ).all()
    )

    # Fetch all activities for the course in one query, keyed by chapter_number.
    all_acts = db.scalars(
        select(Activity)
        .where(Activity.tenant_id == tenant_id)
        .where(Activity.course_id == course_id)
    ).all()
    acts_by_chapter: dict[int | None, list[Activity]] = defaultdict(list)
    for act in all_acts:
        acts_by_chapter[act.chapter_number].append(act)

    passed_act_ids = {aid for aid, s in best.items() if s.passed}

    # Group chapters by part, preserving encounter order of parts.
    seen_parts: list[str] = []
    parts_map: dict[str, list[CatalogChapter]] = {}
    continue_target: ChapterFact | None = None

    for ch in chapters:
        ch_acts = acts_by_chapter.get(ch.number, [])
        ch_act_list = tuple(
            CatalogActivity(
                _activity_fact(act),
                bool(best.get(act.id) and best[act.id].passed),
                round(100 * best[act.id].fraction) if best.get(act.id) else 0,
            )
            for act in ch_acts
        )

        chapter_fact = _chapter_fact(ch)

        # continue_target: first chapter where first activity is missing or unpassed
        # (mirrors the learn-home logic so navigation is consistent).
        if continue_target is None:
            first_act = ch_acts[0] if ch_acts else None
            if first_act is None or first_act.id not in passed_act_ids:
                continue_target = chapter_fact

        part_key = ch.part or ""
        if part_key not in seen_parts:
            seen_parts.append(part_key)
            parts_map[part_key] = []
        parts_map[part_key].append(CatalogChapter(chapter_fact, ch_act_list))

    parts = tuple(CatalogPart(pk, tuple(parts_map[pk])) for pk in seen_parts)

    # Course-level activities (mid/final assessments) carry no chapter_number, so
    # they belong to no chapter card and were previously rendered nowhere at all —
    # invisible to learners while still counting towards completion, which made
    # every affected course impossible to finish. They surface as their own
    # section after the chapters.
    course_activities = tuple(
        CatalogActivity(
            _activity_fact(act),
            bool(best.get(act.id) and best[act.id].passed),
            round(100 * best[act.id].fraction) if best.get(act.id) else 0,
        )
        for act in sorted(acts_by_chapter.get(None, []), key=lambda a: a.title)
    )
    return CourseStructure(
        parts,
        course_activities,
        continue_target,
        locked,
    )


__all__ = ["my_courses", "all_courses", "course_completion", "course_structure"]

"""Caller-transaction CURRENT transfer of all fourteen learning storage tables.

V1 remains a seven-table protocol. V2 qualifies fourteen tables, validates every
representation and actual FK edge before ANY insert, then reuses the V1 writer
and writes only the added seven tables. No connection or transaction is created
or completed here. Academy still owns writer fences, external reference/ACK
closure, grants, compatible reverse storage, authorization and source selection.
