"""Course entitlement checks.

Single source of truth for "may this person study this course?". Access requires
an active Enrollment tying the person to a Cohort that has an active
CourseOffering for the course. Discipline strings do not grant access.
"""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass
from datetime import UTC, datetime
from uuid import UUID

from sqlalchemy import Row, or_, select
from sqlalchemy.orm import Session

from .models import Course, CourseCompletion
from .participation_contracts import ParticipationForbidden
from .participation_models import (
    CourseOffering,
    CoursePrerequisite,
    Enrollment,
    TrackCourse,
)


class CourseAccessDenied(ParticipationForbidden):
    """Product adapter maps status_code/detail to its existing HTTP response."""

    status_code = 403

    def __init__(self, detail: str = "Forbidden") -> None:
        super().__init__(detail)
        self.detail = detail


@dataclass(frozen=True)
class CourseAccessState:
    course_id: UUID
    locked: bool
    locked_reason: str | None = None
    locked_until_course_id: UUID | None = None


def _course_lock_reason(title: str | None, fallback: str) -> str:
    if title:
        return f'Complete "{title}" to unlock this course.'
    return fallback


def _entitled_course_rows(
    db: Session, *, tenant_id: UUID, person_id: UUID
) -> Sequence[Row[tuple[UUID, UUID | None, int | None, str]]]:
    return db.execute(
        select(
            CourseOffering.course_id,
            Enrollment.track_id,
            TrackCourse.order_index,
            Course.title,
        )
        .distinct()
        .join(
            Enrollment,
            (Enrollment.cohort_id == CourseOffering.cohort_id)
            & (Enrollment.tenant_id == CourseOffering.tenant_id),
        )
        .join(
            Course,
            (Course.id == CourseOffering.course_id)
            & (Course.tenant_id == CourseOffering.tenant_id),
        )
        .outerjoin(
            TrackCourse,
            (TrackCourse.tenant_id == Enrollment.tenant_id)
            & (TrackCourse.track_id == Enrollment.track_id)
            & (TrackCourse.course_id == CourseOffering.course_id),
        )
        .where(CourseOffering.tenant_id == tenant_id)
        .where(CourseOffering.status == "active")
        .where(Course.status.in_(("published", "completed")))
        .where(Enrollment.person_id == person_id)
        .where(Enrollment.status == "active")
        .where(or_(Enrollment.track_id.is_(None), TrackCourse.id.isnot(None)))
        .order_by(Enrollment.track_id, TrackCourse.order_index, Course.title)
    ).all()


def visible_course_ids(db: Session, *, tenant_id: UUID, person_id: UUID) -> set[UUID]:
    """Course ids the person is entitled to see, including locked track courses."""
    return {
        course_id
        for course_id, _track_id, _order_index, _title in _entitled_course_rows(
            db, tenant_id=tenant_id, person_id=person_id
        )
    }


def course_access_states(
    db: Session, *, tenant_id: UUID, person_id: UUID
) -> dict[UUID, CourseAccessState]:
    """Access state for entitled courses.

    Track-assigned enrollments unlock courses in track order using the existing
    CourseCompletion.status == "completed" record for the immediately previous
    track course. Null-track enrollments preserve legacy cohort-wide access.
    """
    rows = _entitled_course_rows(db, tenant_id=tenant_id, person_id=person_id)
    if not rows:
        return {}

    completed = set(
        db.scalars(
            select(CourseCompletion.course_id)
            .where(CourseCompletion.tenant_id == tenant_id)
            .where(CourseCompletion.person_id == person_id)
            .where(CourseCompletion.status == "completed")
        ).all()
    )

    track_sequences: dict[UUID, list[UUID]] = {}
    legacy_courses: set[UUID] = set()
    course_titles = {
        course_id: title for course_id, _track_id, _order_index, title in rows
    }
    for course_id, track_id, _order_index, _title in rows:
        if track_id is None:
            legacy_courses.add(course_id)
            continue
        track_sequences.setdefault(track_id, [])
        if course_id not in track_sequences[track_id]:
            track_sequences[track_id].append(course_id)

    states: dict[UUID, CourseAccessState] = {
        course_id: CourseAccessState(course_id=course_id, locked=False)
        for course_id in legacy_courses
    }
    for sequence in track_sequences.values():
        for index, course_id in enumerate(sequence):
            previous_course_id = sequence[index - 1] if index > 0 else None
            state = (
                CourseAccessState(course_id=course_id, locked=False)
                if previous_course_id is None or previous_course_id in completed
                else CourseAccessState(
                    course_id=course_id,
                    locked=True,
                    locked_reason=_course_lock_reason(
                        course_titles.get(previous_course_id),
                        "Complete the previous course to unlock this course.",
                    ),
                    locked_until_course_id=previous_course_id,
                )
            )
            current = states.get(course_id)
            if current is None or current.locked:
                states[course_id] = state

    # Explicit CoursePrerequisite rules apply on top of track order: a course
    # with an uncompleted required course is locked even when track order (or a
    # null track) would otherwise open it. Without this, the dashboard shows
    # Start and the chapter route then 403s (require_course_open checks these).
    entitled_ids = [course_id for course_id, _t, _o, _title in rows]
    prereq_rows = db.execute(
        select(CoursePrerequisite.course_id, CoursePrerequisite.requires_course_id)
        .where(CoursePrerequisite.tenant_id == tenant_id)
        .where(CoursePrerequisite.course_id.in_(entitled_ids))
    ).all()
    missing_title_ids = {
        requires_course_id
        for _course_id, requires_course_id in prereq_rows
        if requires_course_id not in course_titles
    }
    if missing_title_ids:
        missing_title_rows = db.execute(
            select(Course.id, Course.title)
            .where(Course.tenant_id == tenant_id)
            .where(Course.id.in_(missing_title_ids))
        ).all()
        course_titles.update(dict(missing_title_rows))
    for course_id, requires_course_id in prereq_rows:
        if requires_course_id in completed:
            continue
        current = states.get(course_id)
        if current is not None and current.locked:
            continue  # already locked (track order); keep the first reason
        states[course_id] = CourseAccessState(
            course_id=course_id,
            locked=True,
            locked_reason=_course_lock_reason(
                course_titles.get(requires_course_id),
                "Complete the prerequisite course to unlock this course.",
            ),
            locked_until_course_id=requires_course_id,
        )
    return states


def accessible_course_ids(
    db: Session, *, tenant_id: UUID, person_id: UUID
) -> set[UUID]:
    """Course ids the person may currently access/start."""
    return {
        course_id
        for course_id, state in course_access_states(
            db, tenant_id=tenant_id, person_id=person_id
        ).items()
        if not state.locked
    }


def person_can_access_course(
    db: Session, *, tenant_id: UUID, person_id: UUID, course_id: UUID
) -> bool:
    state = course_access_states(db, tenant_id=tenant_id, person_id=person_id).get(
        course_id
    )
    return bool(state and not state.locked)


def require_course_access(
    db: Session, *, tenant_id: UUID, person_id: UUID, course_id: UUID
) -> None:
    """Raise 403 if the person is not entitled to the course."""
    if not person_can_access_course(
        db, tenant_id=tenant_id, person_id=person_id, course_id=course_id
    ):
        raise CourseAccessDenied()


def open_course_ids(
    db: Session, *, tenant_id: UUID, person_id: UUID, now: datetime | None = None
) -> set[UUID]:
    """Entitled course ids whose offering window is currently open.

    A null window edge is open-ended; a fully null window is always open.
    """
    now = now or datetime.now(UTC)
    rows = db.scalars(
        select(CourseOffering.course_id)
        .distinct()
        .join(
            Enrollment,
            (Enrollment.cohort_id == CourseOffering.cohort_id)
            & (Enrollment.tenant_id == CourseOffering.tenant_id),
        )
        .join(
            Course,
            (Course.id == CourseOffering.course_id)
            & (Course.tenant_id == CourseOffering.tenant_id),
        )
        .outerjoin(
            TrackCourse,
            (TrackCourse.tenant_id == Enrollment.tenant_id)
            & (TrackCourse.track_id == Enrollment.track_id)
            & (TrackCourse.course_id == CourseOffering.course_id),
        )
        .where(CourseOffering.tenant_id == tenant_id)
        .where(CourseOffering.status == "active")
        .where(Course.status.in_(("published", "completed")))
        .where(Enrollment.person_id == person_id)
        .where(Enrollment.status == "active")
        .where(or_(Enrollment.track_id.is_(None), TrackCourse.id.isnot(None)))
        .where(or_(CourseOffering.starts_at.is_(None), CourseOffering.starts_at <= now))
        .where(
            or_(
                CourseOffering.ends_at.is_(None),
                CourseOffering.ends_at >= now,
                Enrollment.access_ends_at >= now,
            )
        )
    ).all()
    return set(rows)


def unmet_prerequisites(
    db: Session, *, tenant_id: UUID, person_id: UUID, course_id: UUID
) -> list[UUID]:
    """Prerequisite course ids the person has not yet completed."""
    required = list(
        db.scalars(
            select(CoursePrerequisite.requires_course_id)
            .where(CoursePrerequisite.tenant_id == tenant_id)
            .where(CoursePrerequisite.course_id == course_id)
        ).all()
    )
    state = course_access_states(db, tenant_id=tenant_id, person_id=person_id).get(
        course_id
    )
    if state is not None and state.locked and state.locked_until_course_id is not None:
        required.append(state.locked_until_course_id)
    if not required:
        return []
    completed = set(
        db.scalars(
            select(CourseCompletion.course_id)
            .where(CourseCompletion.tenant_id == tenant_id)
            .where(CourseCompletion.person_id == person_id)
            .where(CourseCompletion.status == "completed")
            .where(CourseCompletion.course_id.in_(set(required)))
        ).all()
    )
    return [cid for cid in required if cid not in completed]


def require_course_open(
    db: Session,
    *,
    tenant_id: UUID,
    person_id: UUID,
    course_id: UUID,
    now: datetime | None = None,
) -> None:
    """Raise 403 if not entitled, the offering window isn't open, or a
    prerequisite course is not yet completed."""
    if course_id not in open_course_ids(
        db, tenant_id=tenant_id, person_id=person_id, now=now
    ):
        raise CourseAccessDenied()
    if unmet_prerequisites(
        db, tenant_id=tenant_id, person_id=person_id, course_id=course_id
    ):
        raise CourseAccessDenied("Complete the previous course to unlock this course.")

"""Source weighted grades; assessment ranking retains its existing owner."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from uuid import UUID

from sqlalchemy import select
from sqlalchemy.orm import Session

from .gradebook_contracts import (
    ActivityGrade,
    AttemptedGrade,
    CohortGradebook,
    CourseGrade,
    GradebookCell,
    GradebookRow,
)
from .models import Activity
from .progress_contracts import ScoreFact
from .projections import best_scores_for
from .references import ActivityFact, _activity_fact
from .reports import _best_for_person, _cohort, _cohort_activities, _students


def grade_from(
    activities: Sequence[ActivityFact], best: Mapping[UUID, ScoreFact]
) -> CourseGrade:
    if not activities:
        return CourseGrade(0, ())
    per_activity = tuple(
        ActivityGrade(
            a, best[a.id].fraction if a.id in best else 0.0, a.weight, a.id in best
        )
        for a in activities
    )
    total_weight = sum(a.weight for a in activities)
    if total_weight == 0:
        return CourseGrade(0, per_activity)
    weighted_sum = sum(
        (best[a.id].fraction if a.id in best else 0.0) * a.weight for a in activities
    )
    return CourseGrade(int(round(weighted_sum / total_weight * 100)), per_activity)


def course_grade(
    db: Session, *, tenant_id: UUID, person_id: UUID, course_id: UUID
) -> CourseGrade:
    activities = db.scalars(
        select(Activity)
        .where(Activity.tenant_id == tenant_id)
        .where(Activity.course_id == course_id)
        .order_by(Activity.chapter_number, Activity.type)
    ).all()
    best = best_scores_for(
        db, tenant_id=tenant_id, person_id=person_id, course_id=course_id
    )
    return grade_from(tuple(_activity_fact(a) for a in activities), best)


def attempted_from(grade: CourseGrade) -> AttemptedGrade:
    total_weight = sum(a.weight for a in grade.per_activity)
    graded = [a for a in grade.per_activity if a.graded]
    graded_weight = sum(a.weight for a in graded)
    if graded_weight == 0:
        return AttemptedGrade(0, len(graded), 0.0)
    weighted_sum = sum(a.fraction * a.weight for a in graded)
    return AttemptedGrade(
        int(round(weighted_sum / graded_weight * 100)),
        len(graded),
        (graded_weight / total_weight) if total_weight else 0.0,
    )


def attempted_grade(
    db: Session, *, tenant_id: UUID, person_id: UUID, course_id: UUID
) -> AttemptedGrade:
    return attempted_from(
        course_grade(db, tenant_id=tenant_id, person_id=person_id, course_id=course_id)
    )


def cohort_gradebook(
    db: Session, *, tenant_id: UUID, cohort_id: UUID
) -> CohortGradebook:
    cohort = _cohort(db, tenant_id, cohort_id)
    activities, course_ids = _cohort_activities(db, tenant_id, cohort_id)
    total_weight = sum(a.weight for a in activities)
    rows = []
    for p in _students(db, tenant_id, cohort_id):
        best = _best_for_person(db, tenant_id, p.id, course_ids)
        cells = tuple(
            GradebookCell(
                a.id, int(round((best[a.id].fraction if a.id in best else 0.0) * 100))
            )
            for a in activities
        )
        if total_weight > 0:
            weighted_sum = sum(
                (best[a.id].fraction if a.id in best else 0.0) * a.weight
                for a in activities
            )
            final_pct = int(round(weighted_sum / total_weight * 100))
        else:
            final_pct = 0
        rows.append(GradebookRow(p, p.email, cells, final_pct))
    return CohortGradebook(
        cohort, tuple(_activity_fact(a) for a in activities), tuple(rows)
    )

