)


def _cohort(db: Session, tenant_id: UUID, cohort_id: UUID) -> ReportCohort:
    row = db.scalars(
        select(Cohort).where(Cohort.tenant_id == tenant_id, Cohort.id == cohort_id)
    ).first()
    if row is None:
        raise ParticipationNotFound("cohort not found for tenant")
    return ReportCohort(
        **{field: getattr(row, field) for field in ReportCohort.__dataclass_fields__}
    )


def _cohort_activities(
    db: Session, tenant_id: UUID, cohort_id: UUID
) -> tuple[list[Activity], list[UUID]]:
    course_ids = db.scalars(
        select(CourseOffering.course_id)
        .where(CourseOffering.tenant_id == tenant_id)
        .where(CourseOffering.cohort_id == cohort_id)
        .where(CourseOffering.status == "active")
    ).all()
    if not course_ids:
        return [], []
    activities = db.scalars(
        select(Activity)
        .where(Activity.tenant_id == tenant_id)
        .where(Activity.course_id.in_(course_ids))
        .order_by(Activity.chapter_number, Activity.type)
    ).all()
    return list(activities), list(course_ids)


def _best_for_person(
    db: Session, tenant_id: UUID, person_id: UUID, course_ids: Sequence[UUID]
) -> dict[UUID, ScoreFact]:
    best: dict[UUID, ScoreFact] = {}
    for cid in course_ids:
        best.update(
            best_scores_for(db, tenant_id=tenant_id, person_id=person_id, course_id=cid)
        )
    return best


def _person(party: Party, profile: PartyPerson) -> ReportPerson:
    return ReportPerson(
        party.id, party.tenant_id, profile.first_name, profile.last_name, party.email
    )


def _students(
    db: Session, tenant_id: UUID, cohort_id: UUID
) -> tuple[ReportPerson, ...]:
    rows = db.execute(
        select(Party, PartyPerson)
        .join(PartyPerson, PartyPerson.party_id == Party.id)
        .join(
            Enrollment,
            (Enrollment.person_id == Party.id)
            & (Enrollment.tenant_id == Party.tenant_id),
        )
        .where(Enrollment.tenant_id == tenant_id)
        .where(Enrollment.cohort_id == cohort_id)
        .where(Enrollment.role_in_cohort == "student")
        .where(Enrollment.status == "active")
        .order_by(PartyPerson.last_name, PartyPerson.first_name, Party.email)
    ).all()
    return tuple(_person(party, profile) for party, profile in rows)


def _score(score: Score | ScoreFact) -> ReportScore:
    return ReportScore(
        **{field: getattr(score, field) for field in ReportScore.__dataclass_fields__}
    )


def cohort_matrix(db: Session, *, tenant_id: UUID, cohort_id: UUID) -> CohortMatrix:
    cohort = _cohort(db, tenant_id, cohort_id)
    activities, course_ids = _cohort_activities(db, tenant_id, cohort_id)
    total = len(activities)
    rows = []
    for p in _students(db, tenant_id, cohort_id):
        best = _best_for_person(db, tenant_id, p.id, course_ids)
        cells = tuple(
            MatrixCell(a.id, _score(best[a.id]) if a.id in best else None)
            for a in activities
        )
        passing = sum(
            1 for a in activities if best.get(a.id) is not None and best[a.id].passed
        )
        rows.append(
            MatrixRow(
                p.id,
                p.first_name,
                p.last_name,
                p.email,
                cells,
                (passing / total) if total else 0.0,
            )
        )
    return CohortMatrix(
        cohort, tuple(_activity_fact(a) for a in activities), tuple(rows)
    )


_S = TypeVar("_S", Score, ScoreFact)


def _fraction_winner(current: _S | None, candidate: _S) -> _S:
    return (
        candidate
        if current is None or candidate.fraction > current.fraction
        else current
    )


def _transcript_query(
    tenant_id: UUID, person_id: UUID
) -> Select[tuple[Activity, Score]]:
    return (
        select(Activity, Score)
        .join(
            Submission,
            (Submission.activity_id == Activity.id)
            & (Submission.tenant_id == Activity.tenant_id),
        )
        .join(
            Score,
            (Score.submission_id == Submission.id)
            & (Score.tenant_id == Submission.tenant_id),
        )
        .where(Activity.tenant_id == tenant_id)
        .where(Submission.person_id == person_id)
        .order_by(Activity.chapter_number, Activity.type)
    )


def student_transcript(
    db: Session, *, tenant_id: UUID, person_id: UUID
) -> StudentTranscript:
    row = db.execute(
        select(Party, PartyPerson)
        .join(PartyPerson, PartyPerson.party_id == Party.id)
        .where(Party.tenant_id == tenant_id, Party.id == person_id)
    ).first()
    if row is None:
        raise ReportNotFound("person not found for tenant")
    person = _person(row[0], row[1])
    pairs = db.execute(_transcript_query(tenant_id, person_id)).all()
    best: dict[UUID, tuple[Activity, Score]] = {}
    for activity, score in pairs:
        cur = best.get(activity.id)
        if cur is None or _fraction_winner(cur[1], score) is score:
            best[activity.id] = (activity, score)
    rows = tuple(
        TranscriptRow(
            _activity_fact(activity),
            _score(score),
            score.fraction,
            score.passed,
            score.created_at,
            score.source,
        )
        for activity, score in sorted(
            best.values(),
            key=lambda t: (
                t[0].chapter_number if t[0].chapter_number is not None else 0,
                t[0].type,
            ),
        )
    )
    return StudentTranscript(person, rows)

"""Academy scheduling policy in the caller transaction, returning detached facts.

The product parses/localizes times and applies its global instructor guard before
commands. Invalid updates retain source mutations; the caller must roll back.
"""

from __future__ import annotations

from dataclasses import fields
from datetime import datetime
from uuid import UUID

from dotmac_kernel.audit import write_audit_event
from sqlalchemy import Select, select
from sqlalchemy.orm import Session

from .attempt_contracts import AttemptAuditContext
from .delivery_contracts import (
    CancelSessionCommand,
    ClassSessionFact,
    CohortDeliveryFact,
    CreateSessionCommand,
    PersonSession,
    PersonTimetable,
    SchedulingBadRequest,
    SchedulingNotFound,
    SessionChange,
    SessionUpdate,
    SetDeliveryModeCommand,
    UpdateSessionCommand,
)
from .delivery_models import SESSION_STATUSES, SESSION_TYPES, ClassSession
from .participation_models import Cohort, Enrollment
from .results import _transaction, _unchanged

DELIVERY_MODES = frozenset({"self_paced", "live", "blended"})
_TYPES = frozenset(SESSION_TYPES)
_STATUSES = frozenset(SESSION_STATUSES)


def _clean_join_url(value: str | None) -> str | None:
    value = (value or "").strip()
    if not value:
        return None
    if not value.lower().startswith(("http://", "https://")):
        raise SchedulingBadRequest("Join URL must start with http:// or https://.")
    return value


def _fact(row: ClassSession) -> ClassSessionFact:
    return ClassSessionFact(
        **{field.name: getattr(row, field.name) for field in fields(ClassSessionFact)}
    )


def _cohort(db: Session, tenant_id: UUID, cohort_id: UUID) -> Cohort:
    row = db.scalar(
        select(Cohort).where(Cohort.tenant_id == tenant_id, Cohort.id == cohort_id)
    )
    if row is None:
        raise SchedulingNotFound("Cohort not found.")
    return row


def _session(db: Session, tenant_id: UUID, session_id: UUID) -> ClassSession:
    row = db.scalar(
        select(ClassSession).where(
            ClassSession.tenant_id == tenant_id, ClassSession.id == session_id
        )
    )
    if row is None:
        raise SchedulingNotFound("Session not found.")
    return row


def set_delivery_mode(
    db: Session, payload: SetDeliveryModeCommand
) -> CohortDeliveryFact:
    boundary = _transaction(db)
    if payload.mode not in DELIVERY_MODES:
        raise SchedulingBadRequest(f"Unknown delivery mode: {payload.mode}")
    cohort = _cohort(db, payload.tenant_id, payload.cohort_id)
    cohort.delivery_mode = payload.mode
    db.flush()
    _unchanged(db, boundary)
    return CohortDeliveryFact(cohort.id, cohort.tenant_id, cohort.delivery_mode)


def create_session(db: Session, payload: CreateSessionCommand) -> ClassSessionFact:
    boundary = _transaction(db)
    if payload.session_type not in _TYPES:
        raise SchedulingBadRequest(f"Unknown session type: {payload.session_type}")
    if payload.ends_at is not None and payload.ends_at <= payload.starts_at:
        raise SchedulingBadRequest("ends_at must be after starts_at.")
    join_url = _clean_join_url(payload.join_url)
    cohort = _cohort(db, payload.tenant_id, payload.cohort_id)
    if cohort.delivery_mode == "self_paced":
        cohort.delivery_mode = "blended"
    row = ClassSession(
        **payload.model_dump(exclude={"title", "location", "join_url", "notes"}),
        title=payload.title.strip(),
        location=payload.location or None,
        join_url=join_url or None,
        notes=payload.notes or None,
        status="scheduled",
    )
    db.add(row)
    db.flush()
    _unchanged(db, boundary)
    return _fact(row)


def get_session(db: Session, *, tenant_id: UUID, session_id: UUID) -> ClassSessionFact:
    return _fact(_session(db, tenant_id, session_id))


def list_for_cohort(
    db: Session,
    *,
    tenant_id: UUID,
    cohort_id: UUID,
    upcoming_only: bool = False,
    now: datetime | None = None,
) -> tuple[ClassSessionFact, ...]:
    stmt = select(ClassSession).where(
        ClassSession.tenant_id == tenant_id, ClassSession.cohort_id == cohort_id
    )
    if upcoming_only:
        stmt = stmt.where(
            ClassSession.status == "scheduled",
            ClassSession.starts_at > (now or datetime.now(tz=None).astimezone()),
        )
    return tuple(
        _fact(row) for row in db.scalars(stmt.order_by(ClassSession.starts_at)).all()
    )


def update_session(
    db: Session,
    payload: UpdateSessionCommand,
    *,
    audit_context: AttemptAuditContext,
    actor_party_id: UUID | None = None,
) -> SessionUpdate:
    """Flush even unchanged updates; required Kernel audit follows actual changes.

    Audit failure and invalid resulting intervals propagate without undo. The
    caller owns rollback, including mutations already flushed before audit.
    """
    boundary = _transaction(db)
    if audit_context.tenant_id != payload.tenant_id:
        raise SchedulingBadRequest("Audit context belongs to another tenant.")
    row = _session(db, payload.tenant_id, payload.session_id)
    supplied = payload.model_fields_set
    if "session_type" in supplied and payload.session_type not in _TYPES:
        raise SchedulingBadRequest(f"Unknown session type: {payload.session_type}")
    if "status" in supplied and payload.status not in _STATUSES:
        raise SchedulingBadRequest(f"Unknown status: {payload.status}")
    updates: dict[str, str | datetime | None] = {}
    for key in (
        "title",
        "starts_at",
        "ends_at",
        "session_type",
        "location",
        "join_url",
        "notes",
        "status",
    ):
        if key not in supplied:
            continue
        value = getattr(payload, key)
        if key == "title":
            value = (value or "").strip()
        elif key in {"location", "notes"}:
            value = value or None
        elif key == "join_url":
            value = _clean_join_url(value)
        updates[key] = value
    changes: list[SessionChange] = []
    for key, value in updates.items():
        old = getattr(row, key)
        if old != value:
            changes.append(
                SessionChange(
                    key,
                    old.isoformat() if isinstance(old, datetime) else old,
                    value.isoformat() if isinstance(value, datetime) else value,
                )
            )
            setattr(row, key, value)
    if row.ends_at is not None and row.ends_at <= row.starts_at:
        raise SchedulingBadRequest("ends_at must be after starts_at.")
    db.flush()
    _unchanged(db, boundary)
    if changes:
        write_audit_event(
            db,
            tenant_id=payload.tenant_id,
            actor_type=audit_context.actor_type,
            actor_id=audit_context.actor_id,
            actor_label=audit_context.actor_label,
            actor_party_id=actor_party_id,
            source_application=audit_context.source_application,
            action="scheduling.update_session",
            entity_type="class_session",
            entity_id=str(row.id),
            details={
                "changes": {
                    change.field: {"from": change.from_value, "to": change.to_value}
                    for change in changes
                }
            },
        )
        _unchanged(db, boundary)
    return SessionUpdate(_fact(row), tuple(changes))


def cancel_session(db: Session, payload: CancelSessionCommand) -> ClassSessionFact:
    boundary = _transaction(db)
    row = _session(db, payload.tenant_id, payload.session_id)
    row.status = "cancelled"
    db.flush()
    _unchanged(db, boundary)
    return _fact(row)


def _person_sessions(
    tenant_id: UUID, person_id: UUID
) -> Select[tuple[ClassSession, str]]:
    return (
        select(ClassSession, Cohort.name)
        .join(
            Cohort,
            (Cohort.id == ClassSession.cohort_id)
            & (Cohort.tenant_id == ClassSession.tenant_id),
        )
        .join(
            Enrollment,
            (Enrollment.cohort_id == ClassSession.cohort_id)
            & (Enrollment.tenant_id == ClassSession.tenant_id),
        )
        .where(
            ClassSession.tenant_id == tenant_id,
            Enrollment.person_id == person_id,
            Enrollment.status == "active",
        )
    )


def list_for_person(
    db: Session, *, tenant_id: UUID, person_id: UUID, now: datetime
) -> PersonTimetable:
    upcoming: list[PersonSession] = []
    past: list[PersonSession] = []
    for row, cohort_name in db.execute(
        _person_sessions(tenant_id, person_id).order_by(ClassSession.starts_at)
    ).all():
        entry = PersonSession(_fact(row), cohort_name)
        if row.status == "scheduled" and (row.ends_at or row.starts_at) >= now:
            upcoming.append(entry)
        elif row.status != "cancelled":
            past.append(entry)
    past.reverse()
    return PersonTimetable(tuple(upcoming), tuple(past))


def get_session_for_person(
    db: Session, *, tenant_id: UUID, person_id: UUID, session_id: UUID
) -> PersonSession:
    row = db.execute(
        _person_sessions(tenant_id, person_id).where(ClassSession.id == session_id)
    ).first()
    if row is None:
        raise SchedulingNotFound("Session not found.")
    return PersonSession(_fact(row[0]), row[1])


def join_is_open(
    session: ClassSessionFact, *, now: datetime, lead_minutes: int = 60
) -> bool:
    if not session.join_url or session.status != "scheduled":
        return False
    end = session.ends_at or session.starts_at
    return (session.starts_at - now).total_seconds() <= lead_minutes * 60 and end >= now

"""Source legacy dashboard, behind-pace and search computations.

These policies intentionally differ from insights and instructor workspaces.
There is no account-status predicate in the legacy dashboard, and behind-pace
selection includes student enrollments regardless of enrollment status.
Search preserves ILIKE wildcard behavior and unspecified SQL ordering. Academy
owns snippet extraction from raw chapter HTML and all notification operations.
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from datetime import UTC, datetime, timedelta
from uuid import UUID

from sqlalchemy import func, or_, select
from sqlalchemy.orm import Session

from .curriculum import _fact as _chapter_fact
from .curriculum_models import Chapter
from .entitlements import accessible_course_ids
from .insights import _cohort_course_ids
from .models import Activity, Course, CourseCompletion, Score, Submission
from .participation_models import CourseOffering, Enrollment
from .references import _course_fact
from .reports import _cohort, _students
from .support_contracts import (
    AtRiskCourse,
    CourseRiskReason,
    LegacyCohortOverview,
    LegacyCohortStudent,
    SearchAuthority,
    SearchChapter,
    SearchResults,
)

DEFAULT_BEHIND_THRESHOLD = 0.2
_CAP = 20


def _dashboard_state(
    course_ids: Sequence[UUID],
    pcts: Mapping[UUID, float],
    last_at: datetime | None,
    now: datetime,
    at_risk_pct: float,
    stale_days: int,
) -> tuple[float, bool]:
    completion_pct = (
        sum(pcts.get(cid, 0.0) for cid in course_ids) / len(course_ids)
        if course_ids
        else 0.0
    )
    stale_before = now - timedelta(days=stale_days)
    inactive = last_at is None or last_at < stale_before
    return completion_pct, completion_pct < at_risk_pct and inactive


def cohort_overview(
    db: Session,
    *,
    tenant_id: UUID,
    cohort_id: UUID,
    now: datetime | None = None,
    at_risk_pct: float = 0.5,
    stale_days: int = 14,
) -> LegacyCohortOverview:
    """Legacy completion mean and course-scoped score inactivity, not insights."""
    now = now or datetime.now(UTC)
    cohort = _cohort(db, tenant_id, cohort_id)
    course_ids = _cohort_course_ids(db, tenant_id, cohort_id)
    students = _students(db, tenant_id, cohort_id)
    rows = []
    for p in students:
        pcts: dict[UUID, float] = {}
        if course_ids:
            pcts = {  # noqa: C416 - retain source-shaped selected columns
                cid: pct
                for cid, pct in db.execute(
                    select(CourseCompletion.course_id, CourseCompletion.pct)
                    .where(CourseCompletion.tenant_id == tenant_id)
                    .where(CourseCompletion.person_id == p.id)
                    .where(CourseCompletion.course_id.in_(course_ids))
                ).all()
            }
            last_activity_at = db.scalar(
                select(func.max(Score.created_at))
                .join(
                    Submission,
                    (Submission.id == Score.submission_id)
                    & (Submission.tenant_id == Score.tenant_id),
                )
                .join(
                    Activity,
                    (Activity.id == Submission.activity_id)
                    & (Activity.tenant_id == Submission.tenant_id),
                )
                .where(Score.tenant_id == tenant_id)
                .where(Submission.person_id == p.id)
                .where(Activity.course_id.in_(course_ids))
            )
        else:
            last_activity_at = None
        pct, risk = _dashboard_state(
            course_ids, pcts, last_activity_at, now, at_risk_pct, stale_days
        )
        rows.append(LegacyCohortStudent(p, pct, last_activity_at, risk))
    return LegacyCohortOverview(cohort, tuple(rows))


def _risk_for_window(
    starts_at: datetime | None,
    ends_at: datetime | None,
    pct: float,
    completed: bool,
    now: datetime,
    behind_threshold: float,
) -> tuple[CourseRiskReason, float] | None:
    if completed:
        return None
    if ends_at is not None and ends_at < now:
        return "overdue", 1.0
    if starts_at is not None and ends_at is not None and starts_at < now < ends_at:
        span = (ends_at - starts_at).total_seconds()
        elapsed = (now - starts_at).total_seconds() / span if span > 0 else 0.0
        if pct < elapsed - behind_threshold:
            return "behind", elapsed
    return None


def at_risk_for_person(
    db: Session,
    *,
    tenant_id: UUID,
    person_id: UUID,
    behind_threshold: float = DEFAULT_BEHIND_THRESHOLD,
    now: datetime | None = None,
) -> tuple[AtRiskCourse, ...]:
    now = now or datetime.now(UTC)
    cohort_ids = list(
        db.scalars(
            select(Enrollment.cohort_id)
            .where(Enrollment.tenant_id == tenant_id)
            .where(Enrollment.person_id == person_id)
            .where(Enrollment.role_in_cohort == "student")
        ).all()
    )
    if not cohort_ids:
        return ()
    offerings = db.scalars(
        select(CourseOffering)
        .where(CourseOffering.tenant_id == tenant_id)
        .where(CourseOffering.status == "active")
        .where(CourseOffering.cohort_id.in_(cohort_ids))
    ).all()
    if not offerings:
        return ()
    completions = {
        c.course_id: c
        for c in db.scalars(
            select(CourseCompletion)
            .where(CourseCompletion.tenant_id == tenant_id)
            .where(CourseCompletion.person_id == person_id)
        ).all()
    }
    course_ids = {o.course_id for o in offerings}
    titles = {
        c.id: c.title
        for c in db.scalars(
            select(Course)
            .where(Course.tenant_id == tenant_id)
            .where(Course.id.in_(course_ids))
        ).all()
    }
    results = []
    for off in offerings:
        comp = completions.get(off.course_id)
        pct = comp.pct if comp else 0.0
        risk = _risk_for_window(
            off.starts_at,
            off.ends_at,
            pct,
            comp is not None and comp.status == "completed",
            now,
            behind_threshold,
        )
        if risk is not None:
            reason, expected = risk
            results.append(
                AtRiskCourse(
                    off.course_id, titles.get(off.course_id), reason, pct, expected
                )
            )
    return tuple(results)


def _search_authority(
    tenant_id: UUID, person_id: UUID, authority: SearchAuthority
) -> None:
    if (authority.tenant_id, authority.person_id) != (tenant_id, person_id):
        raise ValueError("search authority does not cover tenant/person")


def search(
    db: Session, *, tenant_id: UUID, person_id: UUID, q: str, authority: SearchAuthority
) -> SearchResults:
    _search_authority(tenant_id, person_id, authority)
    if not q or not q.strip():
        return SearchResults("", (), ())
    term = q.strip()
    pattern = f"%{term}%"
    if authority.is_staff:
        allowed_ids: set[UUID] | None = None
    else:
        allowed_ids = accessible_course_ids(
            db, tenant_id=tenant_id, person_id=person_id
        )
        if not allowed_ids:
            return SearchResults(term, (), ())
    course_q = (
        select(Course)
        .where(Course.tenant_id == tenant_id)
        .where(Course.title.ilike(pattern))
    )
    if allowed_ids is not None:
        course_q = course_q.where(Course.id.in_(allowed_ids))
    course_rows = db.scalars(course_q.limit(_CAP)).all()
    chapter_q = (
        select(Chapter, Course.slug)
        .join(
            Course,
            (Course.id == Chapter.course_id) & (Course.tenant_id == Chapter.tenant_id),
        )
        .where(Chapter.tenant_id == tenant_id)
        .where(or_(Chapter.title.ilike(pattern), Chapter.body_html.ilike(pattern)))
    )
    if allowed_ids is not None:
        chapter_q = chapter_q.where(Chapter.course_id.in_(allowed_ids))
    chapter_rows = db.execute(chapter_q.limit(_CAP)).all()
    return SearchResults(
        term,
        tuple(_course_fact(c) for c in course_rows),
        tuple(SearchChapter(_chapter_fact(c), slug) for c, slug in chapter_rows),
    )

"""Source admin learning metrics and CSV inputs in the caller's read scope.

These reports intentionally retain independent denominators and score policies.
No account availability is inferred from Kernel identity activity. Products own
admissions metrics, recipients, labels, CSV/email rendering and delivery.
"""

from __future__ import annotations

from datetime import UTC, datetime
from typing import cast
from uuid import UUID

from dotmac_kernel.models import Party, PartyPerson
from pydantic import JsonValue
from sqlalchemy import Select, func, select
from sqlalchemy.orm import Session

from . import events, insights, success_queue
from .delivery_models import (
    REASON_INACTIVITY,
    STATUS_OPEN,
    STATUS_RESOLVED,
    SuccessQueueEntry,
)
from .gradebook import course_grade
from .models import (
